css:
/* APOGEE LOUNGE (starship) — theme author guide v1.5, token contract 1.
   A 1970s space-liner observation lounge, seen from inside. Ship-day: cream moulded fibreglass,
   tangerine upholstery, mustard and avocado trim. Night cycle: the same mouldings in warm
   aubergine shadow, lit only by amber floor strips.
   ONE STRUCTURAL IDEA: everything is moulded, nothing is drawn. No flat cards, no outlines.
   Every surface is either RAISED out of the cabin wall (messages, the message box, buttons) or
   SUNK into it (Home cubbies, fields, the chats list). Names sit on stadium nameplates that
   straddle a panel's top lip; avatars sit in bolted portholes; the message box is the window
   sill with one round lit push-button; the top bar is the ceiling valance with its cove light. */

:root {
  --mari-tokens-version: 1;
  --al-font: "Apogee Jost", "Jost", "Futura", "Century Gothic", system-ui, sans-serif;
  --radius: 1.1rem;
  --mari-font-ui: var(--al-font);
  --mari-font-heading: var(--al-font);
  --mari-font-chat: var(--al-font);
  --ov-serif: var(--al-font);
  --mari-chat-font-size: 17px;
  --mari-chat-line-height: 1.6;
  --mari-message-measure: 68ch;
  --mari-paragraph-gap: 0.8em;
  --mari-dialogue-weight: 400;
  --mari-text-outline: 0;
  --mari-min-ui-text: 12px;
  --mari-toast-font-size: 0.9375rem;
  --mari-selected-tint: var(--primary);
  --marinara-theme-accent-pulse: none;
  --glow-primary: transparent;
  --glow-accent: transparent;
  --mari-msg-head-rule: none;
  --mari-home-widget-radius: 1.75rem;
  --mari-home-widget-border-width: 0px;
  --mari-home-widget-font: var(--al-font);
  --mari-home-widget-title-font: var(--al-font);
  --mari-home-widget-title-size: 1.375rem;
  --mari-home-widget-eyebrow-size: 0.75rem;
  --mari-home-widget-text-size: 0.9375rem;
  --mari-home-widget-action-size: 0.9375rem;
  --mari-home-shortcut-size: 0.9375rem;
  --mari-home-shortcut-desc-size: 0.875rem;
  --mari-top-bar-plate-radius: 999px;
  --mari-composer-placeholder: "Say something...";
  --mari-chat-row-art-opacity: 0;
  --mari-phone-avatar: hidden;

  /* one layered backdrop: a weather overlay (empty unless fog/snow), the cabin art, the wall colour */
  --al-overlay: linear-gradient(transparent, transparent);
  --al-bd-pos: center 40%;
  --mari-app-backdrop-layers: var(--al-overlay), var(--mari-app-backdrop) var(--al-bd-pos) / cover no-repeat, var(--al-wall);

  /* moulding recipes (colours come from the scheme blocks) */
  --al-raised:
    inset 0 2px 0 var(--al-hi),
    inset 0 -3px 0 var(--al-lo),
    0 1px 0 var(--al-lo),
    0 5px 0 -1px var(--al-lo2),
    0 16px 26px -14px var(--al-shadow);
  --al-raised-sm:
    inset 0 1.5px 0 var(--al-hi),
    inset 0 -2px 0 var(--al-lo),
    0 3px 0 -1px var(--al-lo2),
    0 8px 14px -8px var(--al-shadow);
  --al-sunk:
    inset 0 3px 7px var(--al-shadow-in),
    inset 0 -1.5px 0 var(--al-hi),
    0 1px 0 var(--al-hi);
  --al-ribs: repeating-linear-gradient(90deg,
    transparent 0 46px, var(--al-rib-lo) 46px 47px, var(--al-rib-hi) 47px 49px, transparent 49px 52px);
}

/* ── SHIP-DAY ─────────────────────────────────────── */
:root[data-theme="light"] {
  --al-wall: #e9dfcc;
  --al-panel: #f6efe2;
  --al-panel-user: #f8dfc9;
  --al-recess: #e3d7c0;
  --al-ink: #2a1f1a;
  --al-mute: #5c4c3b;
  --al-dim: #6e5c48;
  --al-accent: #a13c0b;      /* text-safe tangerine on cream */
  --al-online: #35701c;
  --al-idle: #845806;
  --al-accent-fill: #c04a17; /* upholstery */
  --al-dialogue: #8f3a12;
  --al-on-accent: #fffaf2;
  --al-amber: #845806;
  --al-avocado: #56631c;
  --al-teal: #1d6870;
  --al-violet: #6a3e8c;
  --al-hi: rgba(255, 252, 244, 0.95);
  --al-lo: rgba(150, 126, 92, 0.38);
  --al-lo2: #cdbb9b;
  --al-shadow: rgba(70, 48, 24, 0.42);
  --al-shadow-in: rgba(90, 64, 34, 0.28);
  --al-rib-lo: rgba(120, 96, 64, 0.07);
  --al-rib-hi: rgba(255, 252, 244, 0.28);
  --al-cove: #ffd99a;
  --al-plate: #c04a17;
  --al-plate-user: #1d6870;
  --al-plate-ink: #fffaf2;
  --al-ring: url("theme:ring-day.png");
  --mari-app-backdrop: url("theme:bg-day.webp");
  --mari-art-lightness-1: 82%;
  --mari-art-lightness-2: 74%;
  --mari-art-saturation-1: 45%;
  --mari-art-saturation-2: 40%;
}

/* ── NIGHT CYCLE ──────────────────────────────────── */
:root,
:root[data-theme="dark"] {
  --al-wall: #211a20;
  --al-panel: #2f252c;
  --al-panel-user: #3a261f;
  --al-recess: #19131a;
  --al-ink: #f3e7d5;
  --al-mute: #cbb9a2;
  --al-dim: #ad9a84;
  --al-accent: #ff9a5c;
  --al-online: #8fd16a;
  --al-idle: #f0a040;
  --al-accent-fill: #b14a17;
  --al-dialogue: #f4b98c;
  --al-on-accent: #fff6ea;
  --al-amber: #f0a040;
  --al-avocado: #b9c46a;
  --al-teal: #6fc9cf;
  --al-violet: #c9a0f0;
  --al-hi: rgba(255, 214, 170, 0.13);
  --al-lo: rgba(0, 0, 0, 0.45);
  --al-lo2: #120d11;
  --al-shadow: rgba(0, 0, 0, 0.6);
  --al-shadow-in: rgba(0, 0, 0, 0.55);
  --al-rib-lo: rgba(0, 0, 0, 0.22);
  --al-rib-hi: rgba(255, 210, 160, 0.05);
  --al-cove: #f0a040;
  --al-plate: #b14a17;
  --al-plate-user: #1d6a72;
  --al-plate-ink: #fff6ea;
  --al-ring: url("theme:ring-night.png");
  --mari-app-backdrop: url("theme:bg-night.webp");
  --mari-art-lightness-1: 26%;
  --mari-art-lightness-2: 18%;
  --mari-art-saturation-1: 35%;
  --mari-art-saturation-2: 30%;
}

/* ── shared colour wiring ─────────────────────────── */
:root,
:root[data-theme="dark"],
:root[data-theme="light"] {
  --background: var(--al-wall);
  --foreground: var(--al-ink);
  --card: var(--al-panel);
  --card-foreground: var(--al-ink);
  --popover: var(--al-panel);
  --popover-foreground: var(--al-ink);
  --primary: var(--al-accent-fill);
  --primary-foreground: var(--al-on-accent);
  --secondary: var(--al-recess);
  --secondary-foreground: var(--al-ink);
  --muted: var(--al-recess);
  --muted-foreground: var(--al-mute);
  --accent: color-mix(in srgb, var(--al-accent-fill) 14%, var(--al-panel));
  --accent-foreground: var(--al-ink);
  --destructive: #b3261e;
  --destructive-foreground: #fff;
  --border: color-mix(in srgb, var(--al-ink) 14%, transparent);
  --input: color-mix(in srgb, var(--al-ink) 16%, transparent);
  --ring: var(--al-accent);
  --sidebar: var(--al-wall);
  --sidebar-foreground: var(--al-ink);
  --sidebar-border: transparent;
  --sidebar-accent: var(--al-panel);
  --sidebar-accent-foreground: var(--al-ink);

  --ov-line: color-mix(in srgb, var(--al-ink) 12%, transparent);
  --ov-text: var(--al-ink);
  --ov-muted: var(--al-mute);
  --ov-dim: var(--al-dim);
  --ov-accent: var(--al-accent);
  --ov-hover: color-mix(in srgb, var(--al-ink) 6%, transparent);
  --ov-active-bg: var(--al-panel);
  --ov-mode-conversation: var(--al-teal);
  --ov-mode-roleplay: var(--al-accent);
  --ov-mode-game: var(--al-avocado);
  --mari-mode-conversation: var(--al-teal);
  --mari-mode-roleplay: var(--al-accent);
  --mari-mode-game: var(--al-avocado);
  --mari-home-pink: var(--al-accent);
  --mari-home-violet: var(--al-violet);
  --mari-status-online: var(--al-online);
  --mari-status-idle: var(--al-idle);
  --mari-status-dnd: #c8381e;
  --mari-status-offline: var(--al-dim);
  --mari-gauge-ok: var(--al-avocado);
  --mari-gauge-warn: var(--al-amber);
  --mari-gauge-danger: #c8381e;
  --mari-game-combat: var(--al-accent-fill);
  --mari-game-combat-text: var(--al-on-accent);
  --mari-game-combat-bg: var(--al-accent-fill);
  --mari-game-combat-bg-hover: color-mix(in srgb, var(--al-accent-fill) 85%, #000);
  --mari-game-combat-border: transparent;
  --mari-scrim: color-mix(in srgb, var(--al-recess) 70%, transparent);
  --mari-user-avatar-placeholder: radial-gradient(circle at 35% 30%, #f3c79a, #d9541e 70%);
  --mari-dialogue-color: var(--al-dialogue);
  --mari-message-time: var(--al-dim);
  --mari-message-actions: var(--al-mute);
  --mari-swipe-counter: var(--al-mute);
  --mari-chrome-accent: var(--al-accent);
  --mari-chrome-muted: var(--al-mute);
  --mari-resource-accent: var(--al-accent);
  --mari-ctrlk-conversation: var(--al-teal);
  --mari-ctrlk-roleplay: var(--al-accent);
  --mari-ctrlk-game: var(--al-avocado);
  --mari-lore-constant: var(--al-accent);
  --mari-lore-selective: var(--al-teal);
  --mari-lore-normal: var(--al-dim);
  --mari-focus-ring-color: var(--al-accent);

  --mari-chat-wash: none;
  --mari-chat-header-bg: none;
  --mari-home-wash: transparent;
  --mari-page-veil: color-mix(in srgb, var(--al-wall) 92%, transparent);
  --mari-top-bar-plate: color-mix(in srgb, var(--al-panel) 88%, transparent);
  --mari-top-bar-plate-active: var(--al-panel);

  --mari-home-widget-bg: var(--al-recess);
  --mari-home-widget-border: transparent;
  --mari-home-widget-title-color: var(--al-ink);
  --mari-home-widget-muted: var(--al-mute);
  --mari-home-widget-eyebrow-color: var(--al-plate-ink);
  --mari-home-widget-glow: transparent;
  --mari-card-art-placeholder:
    radial-gradient(circle at 70% 35%, color-mix(in srgb, var(--al-accent-fill) 70%, var(--al-panel)) 0 18%, transparent 19%),
    linear-gradient(160deg, #141a44, #0b1030);
  --mari-stage-empty-bg: url("theme:bg-night.webp") center / cover, #0b1030;
}

/* ═════════ TOP BAR: the ceiling valance with its cove light ═════════ */
:root {
  --mari-top-bar-bg:
    linear-gradient(to top, var(--al-cove) 0 2px, color-mix(in srgb, var(--al-cove) 35%, transparent) 2px 4px, transparent 4px),
    linear-gradient(to bottom, var(--al-hi), transparent 40%),
    var(--al-wall);
}
.ov-topbar {
  font-family: var(--al-font);
  box-shadow: 0 6px 14px -6px var(--al-shadow);
  border-bottom: 0 !important;
}
.ov-tab {
  border-radius: 999px !important;
  border: 0 !important;
  font-weight: 500;
}
.ov-tab.is-on {
  background: var(--al-panel) !important;
  box-shadow: var(--al-raised-sm);
}
.ov-text-btn--library,
.ov-text-btn[aria-pressed="true"] {
  border-radius: 999px;
}

/* ═════════ SIDEBARS: ribbed wall panels, rows are seat-back pills ═════════ */
[data-component="ChatSidebar"],
[data-component="RightPanelDesktop"] {
  background: var(--al-ribs), linear-gradient(90deg, var(--al-wall), color-mix(in srgb, var(--al-wall) 92%, var(--al-lo2))) !important;
  font-family: var(--al-font);
}
[data-component="ChatSidebar"] .mari-sidebar-header > .absolute { display: none; }
.mari-chrome-segmented {
  background: var(--al-recess) !important;
  border: 0 !important;
  border-radius: 999px !important;
  box-shadow: var(--al-sunk);
  padding: 4px !important;
}
.mari-chrome-segmented__button { border-radius: 999px !important; border: 0 !important; }
.mari-chrome-segmented__button[aria-pressed="true"] {
  background: var(--al-panel) !important;
  box-shadow: var(--al-raised-sm);
  color: var(--al-ink) !important;
}
.mari-chrome-field {
  background: var(--al-recess) !important;
  border: 0 !important;
  border-radius: 999px !important;
  box-shadow: var(--al-sunk);
  color: var(--al-ink) !important;
}
[data-chat-row] {
  border-radius: 999px !important;
  border: 0 !important;
}
[data-chat-row][data-selected="true"] {
  background: var(--al-panel) !important;
  box-shadow: var(--al-raised-sm);
}
.ov-new-pill {
  border-radius: 999px !important;
  background: radial-gradient(circle at 50% 20%, color-mix(in srgb, var(--al-accent-fill) 70%, #fff), var(--al-accent-fill) 60%) !important;
  color: var(--al-on-accent) !important;
  box-shadow: var(--al-raised-sm);
  border: 0 !important;
}

/* ═════════ MESSAGES: raised moulded panels with nameplates and portholes ═════════ */
.mari-rp-bubble {
  --al-bubble: var(--al-panel);
  background: var(--al-bubble) !important;
  color: var(--al-ink) !important;
  border-radius: 1.6rem !important;
  overflow: visible !important;
  box-shadow: var(--al-raised) !important;
  margin-top: 0.9rem;
  --tw-ring-shadow: 0 0 #0000 !important;
}
.mari-rp-bubble--user { --al-bubble: var(--al-panel-user); }
.mari-rp-bubble > div { padding: 1.35rem 1.6rem 1.15rem !important; }
.mari-rp-bubble .mari-message-content { color: var(--al-ink); }
.mari-rp-bubble [data-mari-part="header"] { min-height: 1.25rem; }
/* the nameplate: a stadium plate riveted over the panel's top lip */
.mari-rp-bubble .mari-message-name {
  position: absolute;
  top: -0.85rem;
  left: 1.3rem;
  padding: 0.2rem 0.95rem 0.25rem;
  border-radius: 999px;
  background: var(--al-plate);
  color: var(--al-plate-ink) !important;
  font-size: 0.8125rem !important;
  font-weight: 600 !important;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  box-shadow: inset 0 1.5px 0 rgba(255, 255, 255, 0.35), inset 0 -2px 0 rgba(0, 0, 0, 0.22), 0 3px 6px -2px var(--al-shadow);
}
.mari-rp-bubble--user .mari-message-name { left: auto; right: 1.3rem; background: var(--al-plate-user); }
.mari-rp-bubble .ov-rpmsg__grow { order: 1; }
.mari-rp-bubble [data-mari-part="header"] > [data-mari-part="actions"] { order: 3; }
.mari-rp-bubble [data-mari-part="time"] { order: 2; margin-inline: 0.5rem; }
/* your own panel: the plate sits top right, so the time and tools move to the left */
.mari-rp-bubble--user [data-mari-part="time"] { order: 0; margin-inline: 0 0.5rem; }
.mari-rp-bubble--user [data-mari-part="header"] > [data-mari-part="actions"] { order: 0; }
.mari-rp-bubble--user .ov-rpmsg__grow { order: 4; min-width: 7rem; }
.mari-rp-bubble [data-mari-part="time"] { color: var(--mari-message-time) !important; font-size: 0.75rem !important; }

/* phones and narrow columns put the name line above the panel: same nameplate, riveted over the lip,
   and the time rides on its own small raised tag so it never sits half on the backdrop */
[data-mari-part="header"][data-placement="outside"] {
  position: relative;
  z-index: 2;
  align-items: center !important;
  margin-bottom: -1.05rem;
  padding-inline: 1.1rem !important;
}
.mari-message-user [data-mari-part="header"][data-placement="outside"] { justify-content: flex-end; }
[data-mari-part="header"][data-placement="outside"] .mari-message-name {
  padding: 0.2rem 0.9rem 0.25rem;
  border-radius: 999px;
  background: var(--al-plate);
  color: var(--al-plate-ink) !important;
  font-size: 0.8125rem !important;
  font-weight: 600 !important;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  box-shadow: inset 0 1.5px 0 rgba(255, 255, 255, 0.35), inset 0 -2px 0 rgba(0, 0, 0, 0.22), 0 3px 6px -2px var(--al-shadow);
}
.mari-message-user [data-mari-part="header"][data-placement="outside"] .mari-message-name { background: var(--al-plate-user); }
[data-mari-part="header"][data-placement="outside"] [data-mari-part="time"] {
  padding: 0.1rem 0.6rem;
  border-radius: 999px;
  background: var(--al-panel);
  color: var(--al-mute) !important;
  font-size: 0.75rem !important;
  box-shadow: var(--al-raised-sm);
}
[data-mari-part="header"][data-placement="outside"] + .mari-rp-bubble { margin-top: 0; }
[data-mari-part="header"][data-placement="outside"] + .mari-rp-bubble > div { padding-top: 1.5rem !important; }

/* portholes: the avatar sits inside a bolted moulded ring */
.mari-roleplay-message-row [data-mari-part="avatar"] > div {
  position: relative;
  padding: 9px;
  margin-top: 0.4rem;
  background: var(--al-ring) center / 100% 100% no-repeat;
  border-radius: 50%;
  filter: drop-shadow(0 4px 5px var(--al-shadow));
}
.mari-roleplay-message-row [data-mari-part="avatar"] button {
  --tw-ring-shadow: 0 0 #0000 !important;
  box-shadow: inset 0 3px 6px rgba(0, 0, 0, 0.45) !important;
}

/* conversation: the intercom log, a solid channel sunk into the wall on the left of the window,
   so the right half of the window (planet, plant, mug) stays clear */
[data-chat-mode="conversation"] .mari-messages-scroll {
  margin: 0.5rem 1rem 0.25rem;
  border-radius: 2rem;
  background: var(--al-recess);
  box-shadow: var(--al-sunk);
}
@media (min-width: 1024px) {
  [data-chat-mode="conversation"] .mari-messages-scroll { width: min(46rem, 62%); max-width: min(46rem, 62%); align-self: flex-start; }
  [data-chat-mode="conversation"] [data-mari-part="composer"] { width: calc(min(46rem, 62%) + 2rem); max-width: calc(min(46rem, 62%) + 2rem); align-self: flex-start; }
}
[data-chat-mode="conversation"] [data-mari-part="message"] .mari-message { border-radius: 999px; }
[data-chat-mode="conversation"] .mari-message-content { color: var(--al-ink); }
[data-chat-mode="conversation"] .mari-message-name { font-weight: 600; }
[data-chat-mode="conversation"] [data-mari-part="avatar"] button {
  box-shadow: 0 0 0 3px var(--al-panel), 0 0 0 4px var(--al-lo2), 0 3px 6px var(--al-shadow);
}

/* ═════════ COMPOSER: the window sill with one lit push-button ═════════ */
/* the sill is solid down to the floor, so scrolled text never shows underneath the box */
[data-mari-part="composer"] {
  background: linear-gradient(to bottom, transparent 0 1.6rem, var(--al-wall) 1.6rem);
}
.mari-chat-input-box {
  background: linear-gradient(to bottom, var(--al-panel), color-mix(in srgb, var(--al-panel) 88%, var(--al-lo2))) !important;
  border: 0 !important;
  border-radius: 1.9rem !important;
  box-shadow: var(--al-raised) !important;
  --tw-ring-shadow: 0 0 #0000 !important;
  backdrop-filter: none !important;
  padding-top: 0.8rem !important;
  padding-bottom: 0.8rem !important;
}
.mari-chat-input-box:focus-within {
  box-shadow: var(--al-raised), 0 0 0 3px color-mix(in srgb, var(--al-accent) 45%, transparent) !important;
}
.mari-chat-input-textarea { color: var(--al-ink) !important; font-size: 1rem !important; }
.mari-chat-input-textarea::placeholder { color: var(--al-dim) !important; }
.mari-chat-send-btn {
  width: 2.75rem !important;
  height: 2.75rem !important;
  border-radius: 50% !important;
  color: var(--al-on-accent) !important;
  background: radial-gradient(circle at 50% 30%, color-mix(in srgb, var(--al-accent-fill) 55%, #ffe2b8) 0, var(--al-accent-fill) 55%, color-mix(in srgb, var(--al-accent-fill) 70%, #000) 100%) !important;
  box-shadow: inset 0 2px 0 rgba(255, 255, 255, 0.35), inset 0 -3px 0 rgba(0, 0, 0, 0.25), 0 0 0 4px var(--al-recess), 0 0 0 5px var(--al-lo2), 0 0 14px 2px color-mix(in srgb, var(--al-accent-fill) 35%, transparent) !important;
}

/* primary buttons are lit push-buttons; Library cards are moulded tiles */
.ov-btn--primary,
.ov-btn--accent {
  background: var(--al-accent-fill) !important;
  color: var(--al-on-accent) !important;
  border-radius: 999px !important;
  border: 0 !important;
  box-shadow: inset 0 1.5px 0 rgba(255, 255, 255, 0.3), inset 0 -2px 0 rgba(0, 0, 0, 0.22), 0 4px 10px -4px var(--al-shadow);
}
[data-mari-part="card-art"] {
  border-radius: 1.4rem !important;
  box-shadow: inset 0 2px 0 rgba(255, 255, 255, 0.25), inset 0 -3px 0 rgba(0, 0, 0, 0.2), 0 10px 18px -10px var(--al-shadow);
}

/* ═════════ HOME: cubbies sunk into the wall, eyebrows on nameplates ═════════ */
[data-mari-part="home-widget"] {
  box-shadow: var(--al-sunk) !important;
  border: 0 !important;
}
[data-mari-part="home-widget-eyebrow"] {
  display: inline-block;
  width: fit-content;
  padding: 0.2rem 0.85rem 0.25rem;
  border-radius: 999px;
  background: var(--al-plate);
  color: var(--al-plate-ink) !important;
  letter-spacing: 0.08em;
  box-shadow: inset 0 1.5px 0 rgba(255, 255, 255, 0.3), inset 0 -2px 0 rgba(0, 0, 0, 0.2);
}
[data-mari-part="home-widget-title"] { font-weight: 500; letter-spacing: 0.01em; line-height: 1.15; margin-bottom: 0.35rem; }
/* each Home cubby that had a stock picture gets a porthole onto the gas giant instead */
img[data-mari-part="home-art"] {
  /* the stock picture is squeezed to nothing by the padding; the porthole is the background */
  box-sizing: border-box;
  padding: 6.5rem 0 0 6.5rem;
  background: url("theme:porthole.webp") center / contain no-repeat;
  opacity: 1 !important;
  top: 0.9rem !important;
  right: 0.9rem !important;
  width: 6.5rem !important;
  height: 6.5rem !important;
  object-fit: contain;
  filter: drop-shadow(0 6px 8px var(--al-shadow));
}

/* ═════════ DIALOGS & WINDOWS: hatches with a thick moulded rim ═════════ */
.mari-window,
[role="dialog"]:not([data-mari-app-overlay]):not(.fixed.inset-0):not([data-component="GlobalOmnibar"]):not(.ovm-sidepage),
[data-component="GlobalOmnibar.Panel"] {
  border-radius: 1.75rem !important;
  border: 0 !important;
  box-shadow: var(--al-raised), 0 0 0 7px var(--al-wall), 0 0 0 8px var(--al-lo2), 0 30px 60px -20px var(--al-shadow) !important;
}

/* ═════════ GAME ═════════ */
[data-mari-part="message"][data-game-narration] {
  background: var(--al-panel) !important;
  color: var(--al-ink) !important;
  border-radius: 1.75rem !important;
  border: 0 !important;
  box-shadow: var(--al-raised) !important;
}

/* ═════════ WEATHER: space phenomena seen through the viewport ═════════
   rain  -> micrometeor streaks (thin, pale, long)        snow -> drifting ice and hull debris
   fog   -> nebula haze (violet, low tint)                 storm -> ion storm in a nebula:
   violet plasma bolts down the side gutters and a storm viewport backdrop.
   Sun/moon off: the backdrop paints its own gas giant and moon. */
:root {
  --mari-weather-sun: none;
  --mari-weather-moon: none;
  --mari-weather-tint-strength: 0.2;
  --mari-weather-amount: 0.55;
  --mari-weather-strength: 0.85;
  --mari-weather-rain-color: #cfe2ff;
  --mari-weather-rain-length: 2.4;
  --mari-weather-speed: 1.2;
  --mari-weather-snow-image: url("theme:wx-ice-1.png") url("theme:wx-ice-2.png") url("theme:wx-ice-3.png") url("theme:wx-ice-4.png");
  --mari-weather-snow-size: 0.42;
  --mari-weather-fog-color: #8a6bc8;
  --mari-weather-star-color: #fff3dc;
  --mari-weather-dust-color: #ffd99a;
  --mari-weather-firefly-color: #f0a040;
  --mari-weather-lightning-color: #9c6ee8;
  --mari-weather-lightning-bolt: 1.8;
}
:root[data-mari-weather="storm"] {
  --mari-app-backdrop: url("theme:bg-storm.webp");
}
/* fog = nebula haze drifting past the glass: violet and teal clouds laid over the window only */
:root[data-mari-weather="fog"] {
  --al-overlay:
    radial-gradient(ellipse 30% 24% at 30% 42%, rgba(168, 116, 232, 0.62), transparent 72%),
    radial-gradient(ellipse 28% 20% at 68% 30%, rgba(86, 196, 206, 0.5), transparent 72%),
    radial-gradient(ellipse 46% 20% at 50% 60%, rgba(196, 150, 230, 0.5), transparent 75%);
}
/* snow = an ice field: a cold blue glint over the window while the debris drifts by */
:root[data-mari-weather="snow"], :root[data-mari-weather="hail"] {
  --al-overlay: radial-gradient(ellipse 45% 30% at 50% 40%, rgba(170, 210, 255, 0.26), transparent 75%);
}

/* ═════════ PHONE & PORTRAIT TABLET: the tall sleeper-cabin porthole ═════════ */
@media (orientation: portrait) {
  :root[data-theme="light"] { --mari-app-backdrop: url("theme:bg-day-phone.webp"); }
  :root, :root[data-theme="dark"] { --mari-app-backdrop: url("theme:bg-night-phone.webp"); }
  :root[data-mari-weather="storm"] { --mari-app-backdrop: url("theme:bg-storm-phone.webp"); }
  :root { --al-bd-pos: center top; }
}

/* ship-day: the game's coloured text effects are pastel by default; deepen them so they read on cream */
:root[data-theme="light"] .anim-text-flicker { color: #a13c0b !important; }
:root[data-theme="light"] .anim-text-wave { color: #1d6870 !important; }
:root[data-theme="light"] .anim-text-drip { color: #4f6a12 !important; }
:root[data-theme="light"] .anim-text-shake,
:root[data-theme="light"] .anim-text-tremble { color: #a3261c !important; }
:root[data-theme="light"] .anim-text-bounce { color: #845806 !important; }


/* ═════════════════════════ ROUND 2 ═════════════════════════ */

/* ── Weather and a chat's own picture stay outside the glass ──
   The weather canvas ([data-mari-part="weather"]) and a chat's own background picture are masked
   with a picture of the window glass (white = glass, black = frame, sill, plant, mug). The mask is
   sized and placed exactly like the backdrop (cover, centre 40%; phone: cover, centre top), in
   viewport terms, then shifted by the element's own offset (the app publishes
   --mari-chat-ui-inset-left and --mari-top-bar-height). So rain, ice and plasma fall only behind the
   glass, and a chat's picture becomes the view through the window, with the lounge around it. */
:root {
  --al-glass: url("theme:glass.png");
  --al-gw: max(100vw, 177.7778vh);
  --al-gh: max(56.25vw, 100vh);
  --al-gx: calc((100vw - var(--al-gw)) / 2);
  --al-gy: calc((100vh - var(--al-gh)) * 0.4);
}
:root[data-mari-weather="storm"] { --al-glass: url("theme:glass-storm.png"); }
@media (orientation: portrait) {
  :root {
    --al-glass: url("theme:glass-phone.png");
    --al-gw: max(100vw, 46.0123vh);
    --al-gh: max(217.3333vw, 100vh);
    --al-gy: 0px;
  }
  :root[data-mari-weather="storm"] { --al-glass: url("theme:glass-storm-phone.png"); }
}
[data-mari-part="weather"],
img[data-mari-part="backdrop"]:not([data-default-background]) {
  -webkit-mask-image: var(--al-glass);
  mask-image: var(--al-glass);
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-size: var(--al-gw) var(--al-gh);
  mask-size: var(--al-gw) var(--al-gh);
  -webkit-mask-position: calc(var(--al-gx) - var(--mari-chat-ui-inset-left, 0px)) calc(var(--al-gy) - var(--mari-top-bar-height, 0px));
  mask-position: calc(var(--al-gx) - var(--mari-chat-ui-inset-left, 0px)) calc(var(--al-gy) - var(--mari-top-bar-height, 0px));
}
/* Game: the scene picture and the weather start at the window's top-left corner */
[data-chat-mode="game"].mari-card-css { background-color: transparent !important; }
[data-chat-mode="game"] .absolute.inset-0.bg-cover,
[data-chat-mode="game"] [data-mari-part="weather"] {
  -webkit-mask-image: var(--al-glass);
  mask-image: var(--al-glass);
  -webkit-mask-repeat: no-repeat;
  mask-repeat: no-repeat;
  -webkit-mask-size: var(--al-gw) var(--al-gh);
  mask-size: var(--al-gw) var(--al-gh);
  -webkit-mask-position: var(--al-gx) calc(var(--al-gy) - var(--mari-top-bar-height, 0px));
  mask-position: var(--al-gx) calc(var(--al-gy) - var(--mari-top-bar-height, 0px));
}
/* a chat picture seen through the glass is still tinted by the cabin a touch, like a reflection */
img[data-mari-part="backdrop"]:not([data-default-background]) { filter: saturate(0.9) brightness(0.92); }

/* the storm art is the night cabin on standby; the weather layer itself stays a light touch */
:root[data-mari-weather="storm"] { --mari-weather-tint-strength: 0; }

/* ── Home: the window shows above the cubbies ── */
.mari-home-hero {
  min-height: 34vh;
  justify-content: flex-start;
}
.mari-home-hero h1 {
  width: fit-content;
  padding: 0.35rem 1.2rem 0.45rem;
  border-radius: 999px;
  background: var(--al-panel);
  box-shadow: var(--al-raised-sm);
}

/* ── No hairlines left: every chip, button, field and select is a raised or sunk pill ── */
.mari-chrome-control,
.ov-btn:not(.ov-btn--primary):not(.ov-btn--accent),
.ov-chip {
  border: 0 !important;
  border-radius: 999px !important;
  background-color: var(--al-panel) !important;
  box-shadow: var(--al-raised-sm) !important;
}
.mari-chrome-control--selected,
.ov-chip.is-on,
.ov-chip[aria-pressed="true"] {
  background-color: color-mix(in srgb, var(--al-accent-fill) 16%, var(--al-panel)) !important;
}
.ov-recent__mode {
  border: 0 !important;
  border-radius: 999px !important;
  background: var(--al-recess) !important;
  box-shadow: var(--al-sunk);
  color: var(--al-mute) !important;
}
.ov-search,
select,
[data-component="OverhaulSettingsPage"] input:not([type="checkbox"], [type="radio"], [type="range"], [type="color"], [type="file"]),
[data-component="OverhaulLibraryPage"] input:not([type="checkbox"], [type="radio"], [type="range"], [type="color"], [type="file"]),
[data-component="OverhaulSettingsPage"] textarea {
  border: 0 !important;
  border-radius: 999px !important;
  background-color: var(--al-recess) !important;
  box-shadow: var(--al-sunk) !important;
  color: var(--al-ink) !important;
}
[data-component="OverhaulSettingsPage"] textarea { border-radius: 1.1rem !important; }
select { padding-inline: 0.9rem 2rem !important; }
/* Settings: section rules become nameplate-less channels; tabs are raised pills in a sunk track */
.ov-settings__head { border-bottom: 0 !important; }
.ov-settings__tabs { border-bottom: 0 !important; }
.ov-settings__tabs > button {
  border: 0 !important;
  border-radius: 999px !important;
  padding: 0.35rem 0.95rem !important;
}
.ov-settings__tabs > button::after, .ov-settings__tabs > button::before { display: none !important; }
.ov-settings__tabs > button.is-on,
.ov-settings__tabs > button[aria-selected="true"] {
  background: var(--al-panel) !important;
  box-shadow: var(--al-raised-sm) !important;
  border-bottom: 0 !important;
}
[data-component="OverhaulSettingsPage"] [class*="border-b"],
[data-component="OverhaulSettingsPage"] [class*="border-t"] { border-color: transparent !important; }
[data-component="OverhaulSettingsPage"] .ring-1 {
  --tw-ring-shadow: 0 0 #0000 !important;
  border-radius: 1.2rem !important;
  box-shadow: var(--al-sunk) !important;
}
/* the Library tree's chosen row is a seat-back pill too */
[data-component="OverhaulLibraryNav"] :is([aria-current="page"], [aria-selected="true"], .is-on) {
  border-radius: 999px !important;
}
/* full pages sit on a solid wall so the sill line never runs through a form */
:root, :root[data-theme="dark"], :root[data-theme="light"] {
  --mari-page-veil: color-mix(in srgb, var(--al-wall) 97%, transparent);
}

/* ── Night hatch: Ctrl+K and dialogs get a lit collar at night too ── */
:root[data-theme="dark"] :is(.mari-window, [data-component="GlobalOmnibar.Panel"], [role="dialog"]:not([data-mari-app-overlay]):not(.fixed.inset-0):not([data-component="GlobalOmnibar"]):not(.ovm-sidepage)) {
  box-shadow: var(--al-raised), 0 0 0 7px #3a2d35, 0 0 0 8px rgba(240, 160, 64, 0.35), 0 30px 60px -20px #000 !important;
}

/* ── Desktop: the time rides on the nameplate's lip as a small tag; no blank band ── */
@media (min-width: 768px) {
  .mari-rp-bubble [data-mari-part="header"][data-placement="inside"] {
    position: absolute;
    top: -0.85rem;
    left: 1.3rem;
    right: 1.3rem;
    min-height: 0;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    z-index: 2;
  }
  .mari-rp-bubble [data-mari-part="header"][data-placement="inside"] .mari-message-name { position: static; order: 0; }
  .mari-rp-bubble [data-mari-part="header"][data-placement="inside"] [data-mari-part="time"] {
    order: 1;
    margin: 0 !important;
    padding: 0.1rem 0.6rem;
    border-radius: 999px;
    background: var(--al-panel);
    color: var(--al-mute) !important;
    box-shadow: var(--al-raised-sm);
    white-space: nowrap;
    flex-shrink: 0;
  }
  .mari-rp-bubble [data-mari-part="header"][data-placement="inside"] .ov-rpmsg__grow { order: 2; min-width: 0; }
  .mari-rp-bubble [data-mari-part="header"][data-placement="inside"] > [data-mari-part="actions"] {
    order: 3;
    border-radius: 999px;
    background: var(--al-panel);
    box-shadow: var(--al-raised-sm);
    padding: 0 0.35rem;
  }
  .mari-rp-bubble--user [data-mari-part="header"][data-placement="inside"] { flex-direction: row-reverse; }
  .mari-rp-bubble > div { padding-top: 1.5rem !important; }
}
/* swipe and regenerate tools under a reply are a small raised pill, not loose icons */
.ov-rpf--below {
  width: fit-content;
  margin-top: 0.35rem;
  padding: 0.1rem 0.5rem;
  border-radius: 999px;
  background: var(--al-panel);
  box-shadow: var(--al-raised-sm);
}

/* ── Reading: italics a touch heavier, and a soft fade under the ceiling valance ── */
.mari-message-content em, .mari-message-content i { font-weight: 450; }
[data-chat-mode="roleplay"] .mari-messages-scroll {
  -webkit-mask-image: linear-gradient(to bottom, transparent 0, #000 1.75rem);
  mask-image: linear-gradient(to bottom, transparent 0, #000 1.75rem);
}

/* ═════════════════════════ FINAL POLISH ═════════════════════════ */

/* ── Ship-day storm: the day-lit lounge with the storm through the glass (cream walls stay cream) ── */
:root[data-theme="light"][data-mari-weather="storm"] {
  --mari-app-backdrop: url("theme:bg-storm-day.webp");
  --al-glass: url("theme:glass.png");
}
@media (orientation: portrait) {
  :root[data-theme="light"][data-mari-weather="storm"] {
    --mari-app-backdrop: url("theme:bg-storm-day-phone.webp");
    --al-glass: url("theme:glass-phone.png");
  }
}

/* ── A side panel never slices the room: with Library (or the Game pane) open on the right, the
   lounge slides left so the right end of the window, the plant, the mug and the frame stay in view.
   The backdrop and every glass mask share --al-gx, so weather and chat pictures follow. ── */
:root {
  --al-pane-r: 0px;
  --al-gx: calc((100vw - var(--al-gw)) / 2 - max(var(--mari-chat-ui-inset-right, 0px), var(--al-pane-r)));
  --al-bd-pos: var(--al-gx) 40%;
}
:root:has(.ov-gwrap.has-pane) { --al-pane-r: 23.5rem; }
@media (orientation: portrait) {
  :root { --al-bd-pos: var(--al-gx) top; }
}

/* ── Game: the side pane is a ribbed wall panel; its rows are sunk channels; the map card is a hatch ── */
.ov-gpane {
  border-left: 0 !important;
  background: var(--al-ribs), linear-gradient(90deg, color-mix(in srgb, var(--al-wall) 92%, var(--al-lo2)), var(--al-wall)) !important;
  box-shadow: inset 0 3px 0 -1px var(--al-hi), -6px 0 18px -6px var(--al-shadow), -1px 0 0 var(--al-lo2);
  color: var(--al-ink);
  font-family: var(--al-font);
}
.ov-gpane__head, .ov-gpane__tabs { border-bottom: 0 !important; }
.ov-gpane__tabs {
  margin: 0.35rem 0.6rem 0.5rem;
  padding: 4px !important;
  border-radius: 999px;
  background: var(--al-recess);
  box-shadow: var(--al-sunk);
}
.ov-gpane__tabs button { border-radius: 999px !important; color: var(--al-mute) !important; }
.ov-gpane__tabs button.is-on {
  background: var(--al-panel) !important;
  box-shadow: var(--al-raised-sm);
  color: var(--al-accent) !important;
}
.ov-gpane__table { border-collapse: separate !important; border-spacing: 0 6px; }
.ov-gpane__table th { border-bottom: 0 !important; color: var(--al-dim) !important; }
.ov-gpane__table td {
  border: 0 !important;
  background: var(--al-recess);
  box-shadow: inset 0 3px 5px -3px var(--al-shadow-in), inset 0 -1px 0 var(--al-hi);
}
.ov-gpane__table tr > td:first-child { border-radius: 999px 0 0 999px; padding-left: 0.6rem !important; }
.ov-gpane__table tr > td:last-child { border-radius: 0 999px 999px 0; }
.ov-gpane [class*="border-b"], .ov-gpane [class*="border-t"] { border-color: transparent !important; }
[data-tour="game-map"] {
  border: 0 !important;
  border-radius: 1.3rem !important;
  background: var(--al-panel) !important;
  box-shadow: var(--al-raised) !important;
  color: var(--al-mute) !important;
}
[data-tour="game-map"] button {
  border: 0 !important;
  border-radius: 999px !important;
  background: var(--al-recess) !important;
  box-shadow: var(--al-sunk) !important;
}

/* ── Settings: every section is a moulded panel; no hairline rules; tabs are pills in a sunk track ── */
[data-ov-settings-sections] [id^="settings-section-"] {
  padding: 0.85rem 1.1rem 0.7rem !important;
  border-radius: 1.4rem !important;
  background: var(--al-panel) !important;
  box-shadow: var(--al-raised) !important;
}
[data-ov-settings-sections] section[id^="settings-section-"] > div:last-child { border-top: 0 !important; }
[data-ov-settings-sections] section[id^="settings-section-"] > div:last-child > .flex-col > :not(.mari-chrome-control) {
  border-bottom: 0 !important;
}
.ov-settings__tabs [role="tablist"] {
  gap: 0;
  margin: 0.45rem 0 0.2rem;
  padding: 4px;
  border-radius: 999px;
  background: var(--al-recess);
  box-shadow: var(--al-sunk);
}
.ov-settings__tabs [role="tab"] {
  height: 2.2rem !important;
  padding: 0 0.6rem !important;
  border: 0 !important;
  border-radius: 999px !important;
  color: var(--al-mute) !important;
}
.ov-settings__tabs [role="tab"].is-on {
  background: var(--al-panel) !important;
  box-shadow: var(--al-raised-sm) !important;
  color: var(--al-ink) !important;
}
/* the search is one sunk pill, not a pill holding a pill */
.ov-search input,
[data-component="OverhaulSettingsPage"] .ov-search input,
[data-component="OverhaulLibraryPage"] .ov-search input {
  background: transparent !important;
  box-shadow: none !important;
  border: 0 !important;
  outline: none;
}
/* native selects get the theme's own chevron */
select {
  -webkit-appearance: none;
  appearance: none;
  background-image:
    linear-gradient(45deg, transparent 50%, var(--al-mute) 50%),
    linear-gradient(135deg, var(--al-mute) 50%, transparent 50%) !important;
  background-position: calc(100% - 1.15rem) 52%, calc(100% - 0.8rem) 52% !important;
  background-size: 0.36rem 0.36rem !important;
  background-repeat: no-repeat !important;
}
select + svg { display: none; }

/* ── Ctrl+K: sunk search channel, chips and result cards are moulded pills, no hairlines ── */
[data-component="GlobalOmnibar.Panel"] header > div:first-child,
[data-component="GlobalOmnibar.ScopeChips"] { border-bottom: 0 !important; }
[data-component="GlobalOmnibar.Panel"] header > div:first-child > .contents > div.relative {
  padding: 0.5rem 1rem;
  border-radius: 999px;
  background: var(--al-recess);
  box-shadow: var(--al-sunk);
}
[data-omnibar-scope-chip] {
  border-radius: 999px !important;
  background: var(--al-panel);
  box-shadow: var(--al-raised-sm);
  margin-inline: 2px;
}
[data-omnibar-scope-chip][aria-pressed="true"] { background: color-mix(in srgb, var(--al-accent-fill) 18%, var(--al-panel)); }
[data-component="GlobalOmnibar.Results"] [data-command-center-result-row] {
  border: 0 !important;
  --tw-ring-shadow: 0 0 #0000 !important;
  border-radius: 1.2rem !important;
  background: var(--al-panel) !important;
  box-shadow: var(--al-raised-sm) !important;
}
[data-component="GlobalOmnibar.Results"] [data-command-center-result-row]:has([data-selected="true"]) {
  background: color-mix(in srgb, var(--al-accent-fill) 16%, var(--al-panel)) !important;
}
[data-component="GlobalOmnibar.Results"] .ring-1 { --tw-ring-shadow: 0 0 #0000 !important; border-radius: 999px !important; box-shadow: var(--al-sunk) !important; }

/* ── Conversation: no sill stub past the end of the message box ── */
@media (min-width: 1024px) {
  [data-chat-mode="conversation"] [data-mari-part="composer"] { background: none; }
}

/* ── Sidebar: the search gets the whole row, so its placeholder never clips ── */
[data-component="ChatSidebar"] .flex.gap-1\.5:has(> .relative > .mari-chrome-sort-field) { flex-wrap: wrap; row-gap: 0.45rem; }
[data-component="ChatSidebar"] .flex.gap-1\.5:has(> .relative > .mari-chrome-sort-field) > .relative:first-child { flex: 1 0 100%; }
[data-component="ChatSidebar"] .flex.gap-1\.5:has(> .relative > .mari-chrome-sort-field) > .relative:has(> select) { flex: 1; }
[data-component="ChatSidebar"] .mari-chrome-sort-field { width: 100%; }
[data-component="ChatSidebar"] input.mari-chrome-field { font-size: 0.875rem !important; }
/* the Chats badge becomes a tiny porthole onto the gas giant */
[data-component="ChatSidebar"] .mari-sidebar-header > div:nth-child(2) > div:first-child {
  background: url("theme:porthole.webp") center / contain no-repeat !important;
  border-radius: 999px;
  width: 1.9rem; height: 1.9rem;
  box-shadow: none;
}
[data-component="ChatSidebar"] .mari-sidebar-header > div:nth-child(2) > div:first-child > svg { display: none; }

/* ── Night reading: narration italics rest a step back from the dialogue ── */
:root[data-theme="dark"] .mari-message-content :is(em, i) {
  color: color-mix(in srgb, var(--al-ink) 84%, var(--al-panel));
  font-weight: 400;
}

@container ov-settabs (max-width: 47rem) {
  .ov-settings__tabs [role="tab"] { padding: 0 0.45rem !important; }
}
[data-component="GlobalOmnibar.Panel"] [class*="border-t"] { border-top-color: transparent !important; }
.ov-gpane { font-size: 0.875rem; }
/* the game's narration buttons: moulded pills, no hairline */
.mari-game-narration-surface button { border-color: transparent !important; }
.mari-game-narration-surface > .mt-2.flex button {
  border-radius: 999px !important;
  box-shadow: var(--al-raised-sm) !important;
}


/* ═════════════════════════ 1.1: ONE RIGHT SIDEBAR, ONE PAGE WALL ═════════════════════════ */

/* ── Every full page sits on the same solid wall. The app's page veil already covers each page; the
   hook makes it explicit, so Lorebooks, Presets, Regex, Connections, Agents and Tools match Characters,
   and the page's own fields get the sunk channels Settings and Characters had. ── */
[data-mari-part="page"] {
  background: linear-gradient(var(--mari-page-veil), var(--mari-page-veil)) !important;
}
[data-mari-part="page"] :is([data-component="OverhaulSettingsPage"], [data-component="OverhaulLibraryPage"], .ov-gallery, .ov-settings) {
  background: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
}
[data-mari-part="page"] input:not([type="checkbox"], [type="radio"], [type="range"], [type="color"], [type="file"]):not(.ov-search input):not([class*="mari-chrome"]) {
  border: 0 !important;
  border-radius: 999px !important;
  background-color: var(--al-recess) !important;
  box-shadow: var(--al-sunk) !important;
  color: var(--al-ink) !important;
}
[data-mari-part="page"] .ov-search input { background: transparent !important; box-shadow: none !important; }

/* ── The right pane is one ribbed wall panel: the chats list inside it paints no second wall ── */
.ov-sidepane [data-component="ChatSidebar"],
.ovm-sidepage [data-component="ChatSidebar"] {
  background: none !important;
  box-shadow: none !important;
}

/* ── The Chats | Library switch: raised pills in a sunk track, like every other tab set here,
   with the old Chats badge (a porthole onto the gas giant) set into the wall at its left end ── */
.ov-sideswitch {
  align-items: center;
  border: 0;
  border-radius: 999px;
  background: var(--al-recess);
  box-shadow: var(--al-sunk);
  padding: 4px;
  gap: 4px;
}
.ov-sideswitch::before {
  content: "";
  flex: none;
  width: 1.75rem;
  height: 1.75rem;
  margin-left: 2px;
  border-radius: 999px;
  background: url("theme:porthole.webp") center / contain no-repeat;
  pointer-events: none;
}
.ov-sideswitch__btn {
  border-radius: 999px;
  color: var(--al-mute);
  font-family: var(--al-font);
  font-weight: 500;
  font-size: 0.875rem;
}
.ov-sideswitch__btn.is-on {
  background: var(--al-panel);
  box-shadow: var(--al-raised-sm);
  color: var(--al-accent);
  font-weight: 600;
}
@media (hover: hover) {
  .ov-sideswitch__btn:not(.is-on):hover { background: color-mix(in srgb, var(--al-ink) 6%, transparent); color: var(--al-ink); }
}

/* ── Phones and tablets: the side page is the same ribbed wall, sliding in under the top bar ── */
.ovm-sidepage {
  background: var(--al-ribs), linear-gradient(90deg, var(--al-wall), color-mix(in srgb, var(--al-wall) 92%, var(--al-lo2))) !important;
  color: var(--al-ink);
  font-family: var(--al-font);
  box-shadow: inset 0 2px 0 var(--al-hi), -8px 0 22px -10px var(--al-shadow);
  border-top-left-radius: 1.4rem;
}
.ovm-sidepage .ov-sideswitch { margin-top: 0.85rem; }
.ovm-sidepage .ov-sideswitch::before { width: 2.1rem; height: 2.1rem; }
.ovm-sidepage .ovm-stack-menu__row {
  border-radius: 999px;
  color: var(--al-ink);
}
.ovm-sidepage .ovm-stack-menu__row svg { color: var(--al-accent); }
.ovm-sidepage .ovm-sidepage__dock { border-top: 0; }
.ovm-sidepage .ovm-stack-menu__tile {
  border-radius: 1.2rem;
  background: var(--al-panel);
  box-shadow: var(--al-raised-sm);
  color: var(--al-ink);
  margin-block: 0.35rem;
}
.ovm-sidepage .ovm-stack-menu__tile svg { color: var(--al-accent); }

/* ── Day labels on tinted chips a shade deeper, so they clear 4.5:1 ── */
:root[data-theme="light"] .ov-mari-assist { color: #8a3008 !important; }
:root[data-theme="light"] .ov-conn__chip.is-main { color: #3e4810 !important; }
